// Per-hero stage colour - the hue/colour scripts/make-stages.mjs recolours
// stage_base.webp toward for that hero's emote background (see
// src/components/HeroStage.jsx). AUTO_COLORS is generated by
// scripts/extract-hero-colors.py (re-run it after hero art changes, don't
// hand-edit this block - it gets overwritten) from each hero's own
// profile/idle.webp first frame: pixels are bucketed by hue, ignoring
// anything too close to black/white/grey or transparent, and the most
// saturated*bright bin wins.
const AUTO_COLORS = {
  blaze: { stageHue: 5, stageColor: '#bf392e' },
  bolt: { stageHue: 16, stageColor: '#bf7052' },
  comet: { stageHue: 225, stageColor: '#536ebf' },
  cyclone: { stageHue: 14, stageColor: '#bf6f56' },
  nova: { stageHue: 266, stageColor: '#8252bf' },
  phantom: { stageHue: 195, stageColor: '#47a2bf' },
  pulse: { stageHue: 114, stageColor: '#56bf49' },
}

// Hand picks that win over AUTO_COLORS for that hero - add an entry here to
// override anything the script extracted that looks wrong, e.g.:
//   cyclone: { stageHue: 200, stageColor: '#3fa9c9' },
const OVERRIDES = {}

// Same hero stage_base.webp recolours toward for anyone with no manifest at
// all - matches heroManifest.js's own existing "unknown hero borrows
// Blaze's art" fallback, not hero.js's DEFAULT_HERO_NAME (Comet), which is
// about which hero a *player* defaults to, a different concern.
export const DEFAULT_STAGE_HERO = 'blaze'

export function getHeroStageColor(heroName) {
  const key = typeof heroName === 'string' ? heroName.trim().toLowerCase() : ''
  return (
    OVERRIDES[key] ||
    AUTO_COLORS[key] ||
    OVERRIDES[DEFAULT_STAGE_HERO] ||
    AUTO_COLORS[DEFAULT_STAGE_HERO]
  )
}
